{
  "title": "Tokenization-Aware Reward Shaping for Character-Level Reasoning via RLVR",
  "core_problem": "Current RLVR methods treat all tokens uniformly or weight by entropy, but ignore the fundamental role of tokenization structure. Meanwhile, representation-time interventions like StochasTok improve sub-token visibility but lack reward-level reinforcement for correct character reasoning. No existing work bridges these two intervention points.",
  "opportunity": "Outcome-only RL hits a ceiling for character tasks (TASE: 20.4%), motivating process-level reward signals. Yet no work combines tokenization-aware process rewards with RLVR, nor tests whether representation-time (StochasTok) and reward-time interventions are complementary.",
  "change_type": "major"
}
